import{_ as o,W as l,s as d,u as r,ah as i,I as p,Z as e,w as a,A as n}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const k=JSON.parse('{"title":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT x X-CMD","titleTemplate":false,"description":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210520 Make your API better with this positional trick from Python 3.8","title":"用 Python 3.8 中的这个位置技巧让你的 API 变得更好","tag":"202106"},"relativePath":"202106/20210520 Make your API better with this positional trick from Python 3.8.md","filePath":"[post].md"}'),u={name:"202106/20210520 Make your API better with this positional trick from Python 3.8.md"};function h(c,t,m,g,b,y){const s=l("Link");return r(),d("div",null,[t[19]||(t[19]=i('<h1 id="用-python-3-8-中的这个位置技巧让你的-api-变得更好" tabindex="-1">用 Python 3.8 中的这个位置技巧让你的 API 变得更好 <a class="header-anchor" href="#用-python-3-8-中的这个位置技巧让你的-api-变得更好" aria-label="Permalink to 用 Python 3.8 中的这个位置技巧让你的 API 变得更好">​</a></h1><blockquote><p>探索只接受位置参数和其他两个未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/07/164929k51eccocxkx4xf11.jpg" alt=""></p><p>这是 Python 3.x 首发特性系列文章的第九篇。Python 3.8 于 2019 年首次发布，两年后，它的许多很酷的新特性仍然没有被使用。下面是其中的三个。</p><h3 id="importlib-metadata" tabindex="-1">importlib.metadata <a class="header-anchor" href="#importlib-metadata" aria-label="Permalink to importlib.metadata">​</a></h3>',5)),p("p",null,[e(s,{href:"https://packaging.python.org/specifications/entry-points/"},{default:n(()=>t[0]||(t[0]=[a("入口点")])),_:1}),t[2]||(t[2]=a(" 在 Python 包中被用来做各种事情。大多数人熟悉的是 ")),e(s,{href:"https://python-packaging.readthedocs.io/en/latest/command-line-scripts.html"},{default:n(()=>t[1]||(t[1]=[a("console_scripts")])),_:1}),t[3]||(t[3]=a(" 入口点，不过 Python 中的许多插件系统都使用它们。"))]),t[20]||(t[20]=i(`<p>在 Python 3.8 之前，从 Python 中读取入口点的最好方法是使用 <code>pkg_resources</code>，这是一个有点笨重的模块，它是 <code>setuptools</code> 的一部分。</p><p>新的 <code>importlib.metadata</code> 是一个内置模块，它允许访问同样的东西：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from importlib import metadata as importlib_metadata</span></span>
<span class="line"><span></span></span>
<span class="line"><span>distribution = importlib_metadata.distribution(&quot;numpy&quot;)</span></span>
<span class="line"><span>distribution.entry_points</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    [EntryPoint(name=&#39;f2py&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;),</span></span>
<span class="line"><span>     EntryPoint(name=&#39;f2py3&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;),</span></span>
<span class="line"><span>     EntryPoint(name=&#39;f2py3.9&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;)]</span></span></code></pre></div><p>入口点并不是 <code>importlib.metadata</code> 允许访问的唯一东西。可以调试、报告，或者（在极端情况下）触发兼容模式，你也可以在运行时检查依赖的版本！</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>f&quot;{distribution.metadata[&#39;name&#39;]}=={distribution.version}&quot;\`[/code] [code]\`    &#39;numpy==1.20.1&#39;</span></span></code></pre></div><h3 id="只接受位置参数" tabindex="-1">只接受位置参数 <a class="header-anchor" href="#只接受位置参数" aria-label="Permalink to 只接受位置参数">​</a></h3><p>强制关键字的参数在传达 API 作者的意图方面取得巨大成功之后，另一个空白被填补了：只接受位置参数。</p><p>特别是对于那些允许使用任意关键字的函数（例如，生成数据结构），这意味着对允许的参数名称的限制更少：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def some_func(prefix, /, **kwargs):</span></span>
<span class="line"><span>    print(prefix, kwargs)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>some_func(&quot;a_prefix&quot;, prefix=&quot;prefix keyword value&quot;)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   a_prefix {&#39;prefix&#39;: &#39;prefix keyword value&#39;}\`</span></span></code></pre></div><p>注意，令人困惑的是，<em>变量</em> <code>prefix</code> 的值与 <code>kwargs[&quot;prefix&quot;]</code> 的值不同。就像在很多地方一样，要注意小心使用这个功能。</p><h3 id="自我调试表达式" tabindex="-1">自我调试表达式 <a class="header-anchor" href="#自我调试表达式" aria-label="Permalink to 自我调试表达式">​</a></h3><p>50 多年来，<code>print()</code> 语句（及其在其他语言中的对应语句）一直是快速调试输出的最爱。</p><p>但是我们在打印语句方面取得了很大的进展，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>special_number = 5</span></span>
<span class="line"><span>print(&quot;special_number = %s&quot; % special_number)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    special_number = 5</span></span></code></pre></div><p>然而，自我记录的 f-strings 使它更容易明确：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(f&quot;{special_number=}&quot;)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    special_number=5\`</span></span></code></pre></div><p>在 f-string 插值部分的末尾添加一个 <code>=</code>，可以保留字面部分，同时添加数值。</p><p>当更复杂的表达式在该部分内时，这就更有用了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>values = {}</span></span>
<span class="line"><span>print(f&quot;{values.get(&#39;something&#39;, &#39;default&#39;)=}&quot;)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    values.get(&#39;something&#39;, &#39;default&#39;)=&#39;default&#39;</span></span></code></pre></div><h3 id="欢迎来到-2019-年" tabindex="-1">欢迎来到 2019 年 <a class="header-anchor" href="#欢迎来到-2019-年" aria-label="Permalink to 欢迎来到 2019 年">​</a></h3><p>Python 3.8 大约在两年前发布，它的一些新特性非常酷，而且没有得到充分利用。如果你还没使用，那么将他们添加到你的工具箱中。</p><hr>`,28)),p("p",null,[t[5]||(t[5]=a("via: ")),e(s,{href:"https://opensource.com/article/21/5/python-38-features"},{default:n(()=>t[4]||(t[4]=[a("https://opensource.com/article/21/5/python-38-features")])),_:1})]),p("p",null,[t[10]||(t[10]=a("作者：")),e(s,{href:"https://opensource.com/users/moshez"},{default:n(()=>t[6]||(t[6]=[a("Moshe Zadka")])),_:1}),t[11]||(t[11]=a(" 选题：")),e(s,{href:"https://github.com/lujun9972"},{default:n(()=>t[7]||(t[7]=[a("lujun9972")])),_:1}),t[12]||(t[12]=a(" 译者：")),e(s,{href:"https://github.com/geekpi"},{default:n(()=>t[8]||(t[8]=[a("geekpi")])),_:1}),t[13]||(t[13]=a(" 校对：")),e(s,{href:"https://github.com/wxy"},{default:n(()=>t[9]||(t[9]=[a("wxy")])),_:1})]),p("p",null,[t[16]||(t[16]=a("本文由 ")),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>t[14]||(t[14]=[a("LCTT")])),_:1}),t[17]||(t[17]=a(" 原创编译，")),e(s,{href:"https://linux.cn/"},{default:n(()=>t[15]||(t[15]=[a("Linux中国")])),_:1}),t[18]||(t[18]=a(" 荣誉推出"))])])}const P=o(u,[["render",h]]);export{k as __pageData,P as default};
